<?php
namespace Tests\Unit\Ozon;
use App\Models\Brand; use App\Models\Product; use App\Models\ProductAttribute; use App\Services\Ozon\OzonDescriptionBuilder; use Illuminate\Database\Eloquent\Collection; use PHPUnit\Framework\TestCase;
class OzonDescriptionBuilderTest extends TestCase { public function test_builds_clean_description_without_mutating_product(): void { $source='<script>alert(1)</script><p>Описание https://shop.test +7 777 123 45 67</p>';$p=new Product(['name'=>'X','sku'=>'A-1','description'=>$source]);$p->setRelation('brand',new Brand(['name'=>'Brand']));$p->setRelation('attributes',new Collection([new ProductAttribute(['group_name'=>'A','name'=>'Объём','value'=>'100','unit'=>'мл']),new ProductAttribute(['name'=>'Цена','value'=>'10']),new ProductAttribute(['name'=>'Объём','value'=>'100','unit'=>'мл'])]));$result=(new OzonDescriptionBuilder)->build($p);self::assertStringContainsString('Характеристики:', $result);self::assertStringContainsString('Бренд: Brand',$result);self::assertStringContainsString('Артикул: A-1',$result);self::assertSame(1,substr_count($result,'Объём: 100 мл'));self::assertStringNotContainsString('script',$result);self::assertStringNotContainsString('shop.test',$result);self::assertSame($source,$p->description); } }
